package vn.freshlink.quality;
import java.math.*;import java.util.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import vn.freshlink.common.*;import vn.freshlink.common.api.ApiResponse;import vn.freshlink.identity.Actor;
@RestController @RequestMapping("/api/batches") public class ReinspectionController{
 private final JdbcTemplate jdbc;private final Sql sql;private final Idempotency dedup;public ReinspectionController(JdbcTemplate j,Sql s,Idempotency d){jdbc=j;sql=s;dedup=d;}
 public record Request(@NotNull @DecimalMin("0") @Digits(integer=9,fraction=3) BigDecimal accepted,@NotNull @DecimalMin("0") @Digits(integer=9,fraction=3) BigDecimal rejected,@NotBlank @Size(max=1000) String note){}
 @PostMapping("/{id}/reinspect") @Transactional public ApiResponse<?> inspect(@AuthenticationPrincipal Actor a,@PathVariable long id,@jakarta.validation.Valid @RequestBody Request r,@RequestHeader("Idempotency-Key") String key){a.requireRole("QUALITY_INSPECTOR");long result=dedup.execute(a.userId(),key,"REINSPECT_"+id,r.toString(),()->{var rows=jdbc.queryForList("SELECT * FROM batches WHERE batch_id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy lô");var b=rows.get(0);if(!Set.of("QUARANTINED","PARTIALLY_ACCEPTED").contains(b.get("batch_status"))||((BigDecimal)b.get("review_quantity")).signum()==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Lô không có lượng đang cách ly");BigDecimal review=(BigDecimal)b.get("review_quantity");if(r.accepted().add(r.rejected()).compareTo(review)!=0)throw new IllegalArgumentException("Tổng đạt và từ chối phải bằng lượng đang cách ly");BigDecimal accepted=((BigDecimal)b.get("accepted_quantity")).add(r.accepted()),rejected=((BigDecimal)b.get("rejected_quantity")).add(r.rejected());String state=accepted.signum()==0?"REJECTED":rejected.signum()==0?"ACCEPTED":"PARTIALLY_ACCEPTED";int round=jdbc.queryForObject("SELECT COALESCE(MAX(inspection_round),0)+1 FROM batch_inspections WHERE batch_id=?",Integer.class,id);jdbc.update("UPDATE batches SET accepted_quantity=?,review_quantity=0,rejected_quantity=?,batch_status=? WHERE batch_id=?",accepted,rejected,state,id);jdbc.update("UPDATE supply_request_item_orders SET planned_quantity=GREATEST(0,planned_quantity-?) WHERE supply_request_item_id=?",r.rejected(),b.get("supply_request_item_id"));long inspection=sql.insert("INSERT INTO batch_inspections(batch_id,inspection_round,inspector_id,final_result,accepted_quantity,review_quantity,rejected_quantity,general_note) VALUES (?,?,?,?,?,0,?,?)",id,round,a.userId(),r.accepted().signum()>0?(r.rejected().signum()>0?"PARTIAL_PASS":"PASS"):"FAIL",r.accepted(),r.rejected(),r.note());jdbc.update("INSERT INTO audit_logs(actor_user_id,action_code,entity_type,entity_id,new_data) VALUES (?,'REINSPECT_BATCH','BATCH',?,JSON_OBJECT('round',?,'accepted',?,'rejected',?))",a.userId(),id,round,r.accepted(),r.rejected());return inspection;});return ApiResponse.success(result,"Đã hoàn tất kiểm tra lại lô cách ly");}
}
